import sys

def generate_substrings(s):
    substrings = set()
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substrings.add(s[i:j])
    return substrings

def main():
    import sys
    input = sys.stdin.read().split()
    l = int(input[0])
    r = int(input[1])
    n = int(input[2])

    def count_modest_substrings(s):
        count = 0
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                num = int(s[i:j])
                if l <= num <= r:
                    count += 1
        return count

    best_count = 0
    best_string = '9' * n

    for start in range(l, min(r + 1, 10)):
        s = str(start)
        if len(s) > n:
            continue
        queue = [s]
        while queue:
            current = queue.pop(0)
            if len(current) == n:
                current_count = count_modest_substrings(current)
                if current_count > best_count or (current_count == best_count and current < best_string):
                    best_count = current_count
                    best_string = current
            else:
                for digit in range(10):
                    new_s = current + str(digit)
                    if int(new_s) > r:
                        break
                    queue.append(new_s)

    print(best_count)
    print(best_string)

main()
